import {test} from 'node:test';
import assert from 'node:assert/strict';
import {readFile,mkdtemp,rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {OwnerBridge,sha256,canonical} from './core.mjs';
import {LiveHpBridge} from './live-hp.mjs';
import {CampaignBridge,CAMPAIGN_SCOPES,projectCampaignRecord} from './campaign.mjs';
import {SqliteAdapter} from './sqlite-adapter.mjs';
import {handleWorker} from './worker.mjs';
const campaign='campaign-v2-fixture',profile='fixture-player',ownerId='fixture-owner-v2',uuid=()=>crypto.randomUUID();
const owner={ownerId,role:'owner',scopes:[]},connector={ownerId,role:'connector',scopes:[]};
const envelope=(kind,recordId,fields,revision=1)=>({kind,recordId,revision,fields:{...fields,revision,source:'Resolved fictional evidence',updatedAt:1}});
const profileRecord=()=>envelope('character-profile',profile,{id:profile,name:'Fictional Player',currentHp:24,maximumHp:40,temporaryHp:null,armorClass:19,level:9});
const walletRecord=()=>envelope('wallet','fixture-wallet',{id:'fixture-wallet',holderProfileId:profile,name:'Fictional wallet',copper:0,silver:0,gold:100,electrum:null,platinum:10,campaignId:campaign});
const itemRecord=()=>envelope('item','fixture-item',{id:'fixture-item',title:'Fictional metal',category:'Material',owner:'Fictional Player',itemState:'Carried',location:'Actor:'+profile,evidenceStatus:'Confirmed',quantity:4,description:'',knownProperties:'',possibleUses:'',limitations:'',notionPageId:null,archived:false,createdAt:1});
async function setup(t,{readScopes=CAMPAIGN_SCOPES,writeScopes=CAMPAIGN_SCOPES,path=':memory:'}={}){
 const db=new SqliteAdapter(path);db.exec(await readFile(new URL('./schema.sql',import.meta.url),'utf8'));let at=Date.now();const now=()=>at,bridge=new OwnerBridge(db,{ownerId,now}),sync=new CampaignBridge(db,{ownerId,now});const secret='s'.repeat(60),pairing=await bridge.requestPairing({campaignId:campaign,profileId:profile,deviceName:'Fictional V2 device',deviceSecretHash:await sha256(secret),campaignAccess:{readScopes,writeScopes}});const summary=await bridge.pairingSummary(owner,{userCode:pairing.userCode});assert.deepEqual(summary.campaignAccess.readScopes,[...readScopes].sort());await bridge.approvePairing(owner,{userCode:pairing.userCode});const token=await bridge.pollPairing({deviceCode:pairing.deviceCode,deviceSecret:secret});assert.deepEqual(token.scopes,['campaign:sync']);const principal=await bridge.authenticate(token.credentialId,secret);t.after(()=>db.close());return{db,bridge,sync,principal,token,secret,now,setTime:n=>at=n,publish:async records=>sync.publish(principal,campaign,{commandId:uuid(),records:records.map(r=>projectCampaignRecord(r,readScopes))}),enable:async scopes=>sync.configureGrant(principal,campaign,{commandId:uuid(),expectedRevision:(await sync.getGrant(principal,campaign)).grant.revision,autoSyncScopes:scopes}),submit:async ops=>sync.submit(connector,campaign,{commandId:uuid(),expectedGrantRevision:(await sync.getGrant(principal,campaign)).grant.revision,operations:ops,source:'Explicitly resolved fictional action'})};
}
const op=(type,kind,recordId,fields,expectedRevision=1)=>({type,kind,recordId,fields,expectedRevision});
function decision(command,{status='APPLIED',rows=null,scopes=CAMPAIGN_SCOPES}={}){return{commandId:command.commandId,fingerprint:command.fingerprint,status,localReceiptId:status==='APPLIED'?uuid():null,records:status==='APPLIED'?(rows??command.operations.flatMap(o=>[{recordId:o.recordId,kind:o.kind,revision:o.expectedRevision+1,fields:{...o.proposedFields,source:'Saved local provenance',updatedAt:2}},...o.sideEffects.map(x=>({recordId:x.recordId,kind:x.kind,revision:x.expectedRevision+1,fields:{...x.fields,source:'Saved local provenance',updatedAt:2}}))])).map(r=>projectCampaignRecord(r,scopes)):[]};}
const fails=(p,code)=>assert.rejects(p,e=>e.code===code);

test('V2 HP standing grant -> queue only -> Android receipt -> independent saved revision',async t=>{const f=await setup(t);await f.publish([profileRecord()]);await f.enable(['hp']);const {command:c}=await f.submit([op('adjust_hp','character-profile',profile,{delta:-3})]);assert.equal(c.status,'PENDING_DELIVERY');assert.equal((await f.sync.read(connector,campaign,{kinds:['character-profile']})).records[0].fields.currentHp,24);await fails(f.sync.getReceipt(connector,campaign,c.commandId),'RECEIPT_NOT_READY');const b=decision(c),saved=await f.sync.decide(f.principal,campaign,b);assert.equal(saved.receipt.status,'APPLIED');assert.deepEqual(await f.sync.decide(f.principal,campaign,b),saved);assert.deepEqual((await f.sync.getReceipt(connector,campaign,c.commandId)).receipt,saved.receipt);assert.equal((await f.sync.read(connector,campaign,{kinds:['character-profile']})).records[0].fields.currentHp,21);assert.equal((await f.sync.pending(f.principal,campaign)).commands.length,0);assert.throws(()=>f.db.exec('DELETE FROM bridge_campaign_receipts'),/IMMUTABLE_RECEIPT/);});

test('V2 manual mode never auto-commits and disabling standing authorization invalidates an old pending command',async t=>{const f=await setup(t);await f.publish([profileRecord()]);const {command:c}=await f.submit([op('adjust_hp','character-profile',profile,{delta:-3})]);assert.equal(c.status,'PENDING_APPROVAL');const body=decision(c,{status:'REJECTED'});assert.equal((await f.sync.decide(f.principal,campaign,body)).receipt.status,'REJECTED');await f.enable(['hp']);const {command:c2}=await f.submit([op('adjust_hp','character-profile',profile,{delta:-3})]);await f.enable([]);await fails(f.sync.decide(f.principal,campaign,decision(c2)),'GRANT_REVISION_CONFLICT');assert.equal((await f.sync.read(connector,campaign,{kinds:['character-profile']})).records[0].revision,1);});

test('V2 spell slots are their named saved resource; companion resources stay on their own identity',async t=>{const f=await setup(t);const sheet=envelope('party-sheet',profile,{profileId:profile,campaignId:campaign,contentJson:JSON.stringify({resources:[{name:'2nd-level slots',current:3,maximum:3}],conditions:'',senses:'Darkvision'})}),resource=envelope('companion-resource','eek-resource',{id:'eek-resource',companionId:'fixture-eek',name:'Ghostwing',current:2,maximum:3});await f.publish([profileRecord(),sheet,resource]);await f.enable(['resources','companions']);for(const [kind,rid,fields] of [['party-sheet',profile,{resourceName:'2nd-level slots',delta:-1}],['companion-resource','eek-resource',{delta:-1}]]){const {command:c}=await f.submit([op('adjust_resource',kind,rid,fields)]);await f.sync.decide(f.principal,campaign,decision(c));}assert.equal(JSON.parse((await f.sync.read(connector,campaign,{kinds:['party-sheet']})).records[0].fields.contentJson).resources[0].current,2);assert.equal((await f.sync.read(connector,campaign,{kinds:['companion-resource']})).records[0].fields.current,1);assert.equal((await f.sync.read(connector,campaign,{kinds:['character-profile']})).records[0].fields.currentHp,24);});

test('V2 item movement and depletion maintain original item and placement identities atomically',async t=>{const f=await setup(t),container={...itemRecord(),recordId:'fixture-bag',fields:{...itemRecord().fields,id:'fixture-bag',title:'Fictional Bag',quantity:1}};await f.publish([profileRecord(),itemRecord(),container]);await f.enable(['inventory']);const {command:c}=await f.submit([op('move_item','item','fixture-item',{expectedPlacementRevision:null,holderProfileId:profile,containerItemId:'fixture-bag',state:'Stored'})]);await f.sync.decide(f.principal,campaign,decision(c));const moved=(await f.sync.read(connector,campaign,{kinds:['item','item-placement'],recordId:'fixture-item'})).records;assert.equal(moved.length,2);assert.equal(moved.find(x=>x.kind==='item-placement').fields.containerItemId,'fixture-bag');const {command:c2}=await f.submit([op('consume_item','item','fixture-item',{quantity:4},2)]);await f.sync.decide(f.principal,campaign,decision(c2));const after=(await f.sync.read(connector,campaign,{kinds:['item','item-placement'],recordId:'fixture-item'})).records;assert.equal(after.find(x=>x.kind==='item').fields.quantity,0);assert.equal(after.find(x=>x.kind==='item-placement').fields.state,'Consumed');assert.equal(after.find(x=>x.kind==='item-placement').fields.containerItemId,null);});

test('V2 purchase changes currency and new item in one transaction with retry-safe result',async t=>{const f=await setup(t);await f.publish([walletRecord()]);await f.enable(['currency','inventory']);const {command:c}=await f.submit([op('adjust_currency','wallet','fixture-wallet',{goldDelta:-25,platinumDelta:-1}),op('acquire_item','item','new-fictional-tool',{title:'Confirmed fictional tool',quantity:1,evidenceStatus:'Confirmed',itemState:'Carried'},0)]);const b=decision(c),result=await f.sync.decide(f.principal,campaign,b);assert.deepEqual(await f.sync.decide(f.principal,campaign,b),result);assert.equal((await f.sync.read(connector,campaign,{kinds:['wallet']})).records[0].fields.gold,75);assert.equal((await f.sync.read(connector,campaign,{kinds:['item']})).records.length,1);assert.equal((await f.sync.read(connector,campaign,{kinds:['wallet']})).records[0].fields.platinum,9);await fails(f.sync.decide(f.principal,campaign,{...b,records:b.records.slice(1)}),'COMMAND_ID_REUSED');});

test('V2 transaction CAS failure rolls back every mirror row and no successful receipt appears',async t=>{const f=await setup(t);await f.publish([profileRecord(),walletRecord()]);await f.enable(['hp','currency']);const {command:c}=await f.submit([op('adjust_hp','character-profile',profile,{delta:-3}),op('adjust_currency','wallet','fixture-wallet',{goldDelta:-1})]);await f.publish([{...walletRecord(),revision:2,fields:{...walletRecord().fields,revision:2,gold:99}}]);await fails(f.sync.decide(f.principal,campaign,decision(c)),'REVISION_CONFLICT');assert.equal((await f.sync.read(connector,campaign,{kinds:['character-profile']})).records[0].fields.currentHp,24);await fails(f.sync.getReceipt(connector,campaign,c.commandId),'RECEIPT_NOT_READY');});

test('V2 inventory-only grant cannot publish/read HP through legacy scopes or V2 character routes',async t=>{const f=await setup(t,{readScopes:['inventory'],writeScopes:['inventory']});await fails(new LiveHpBridge(f.db,{ownerId,now:f.now}).publishCharacter(f.principal,campaign,{commandId:uuid(),expectedRevision:0,profileId:profile,revision:1,fields:{name:'Fixture',currentHp:24,maximumHp:40,temporaryHp:null,source:'Fixture',updatedAt:1}}),'SCOPE_DENIED');await fails(f.sync.read(connector,campaign,{kinds:['character-profile']}),'READ_SCOPE_DENIED');await fails(f.sync.publish(f.principal,campaign,{commandId:uuid(),records:[profileRecord()]}),'READ_SCOPE_DENIED');await f.publish([itemRecord()]);await fails(f.enable(['hp']),'AUTO_SYNC_SCOPE_DENIED');});

test('V2 per-field read projection and history protection prevent cross-category leaks',async t=>{const f=await setup(t,{readScopes:['character'],writeScopes:['character']});await f.publish([profileRecord()]);const record=(await f.sync.read(connector,campaign,{kinds:['character-profile']})).records[0];assert.equal(record.fields.name,'Fictional Player');assert.equal(Object.hasOwn(record.fields,'currentHp'),false);await fails(f.sync.publish(f.principal,campaign,{commandId:uuid(),records:[profileRecord()]}),'UNAUTHORIZED_RECORD_FIELDS');await fails(f.sync.read(connector,campaign,{kinds:['audit']}),'READ_SCOPE_DENIED');const changed={...record.fields,currentHp:4};await fails(f.submit([op('set_record','character-profile',profile,changed)]),'HP_OPERATION_REQUIRED');});

test('V2 HP-only read omits sheet identity/details and character-only sheet omits resources/conditions',async t=>{for(const scope of ['hp','character']){const f=await setup(t,{readScopes:[scope],writeScopes:[scope]});await f.publish([profileRecord(),envelope('party-sheet',profile,{profileId:profile,campaignId:campaign,contentJson:JSON.stringify({senses:'Private descriptive field',conditions:'Poisoned',resources:[{name:'Slots',current:2,maximum:3}],portraitBase64:'secret-bitmap'})})]);const records=(await f.sync.read(connector,campaign)).records;const sheet=JSON.parse(records.find(x=>x.kind==='party-sheet').fields.contentJson);assert.equal(Object.hasOwn(sheet,'resources'),false);assert.equal(Object.hasOwn(sheet,'portraitBase64'),false);assert.equal(Object.hasOwn(sheet,'conditions'),scope==='hp');assert.equal(Object.hasOwn(sheet,'senses'),scope==='character');}});

test('V2 resource unknown, stale publication, wrong owner/device and revoked grant fail closed',async t=>{const f=await setup(t);await f.publish([{...profileRecord(),fields:{...profileRecord().fields,currentHp:null}},walletRecord()]);await fails(f.submit([op('adjust_hp','character-profile',profile,{delta:-3})]),'RESOURCE_UNKNOWN');await fails(f.submit([op('adjust_currency','wallet','fixture-wallet',{electrumDelta:-1})]),'RESOURCE_UNKNOWN');await fails(f.sync.read({...connector,ownerId:'other'},campaign),'OWNER_SCOPE_DENIED');await fails(f.sync.read({...f.principal,credentialId:'other'},campaign),'DEVICE_SCOPE_DENIED');f.setTime(f.now()+300001);await fails(f.submit([op('adjust_currency','wallet','fixture-wallet',{goldDelta:-1})]),'DEVICE_SYNC_STALE');await f.sync.publish(f.principal,campaign,{commandId:uuid(),records:[],snapshotFingerprint:(await f.sync.mirrorSnapshot(await f.sync.authorize(f.principal,campaign))).fingerprint});assert.equal((await f.sync.read(connector,campaign)).records[0].stale,false);await f.bridge.revokeDevice(f.principal,campaign,f.principal.credentialId);await fails(f.sync.read(connector,campaign),'CAMPAIGN_NOT_AUTHORIZED');});

test('V2 grant event retries are idempotent and expired owner delegation is unusable',async t=>{const f=await setup(t);const b={commandId:uuid(),expectedRevision:1,autoSyncScopes:['hp']},one=await f.sync.configureGrant(f.principal,campaign,b);assert.deepEqual(await f.sync.configureGrant(f.principal,campaign,b),one);await fails(f.sync.configureGrant(f.principal,campaign,{...b,autoSyncScopes:['inventory']}),'COMMAND_ID_REUSED');await fails(f.sync.configureGrant(f.principal,campaign,{...b,commandId:uuid()}),'GRANT_REVISION_CONFLICT');f.setTime(f.now()+31*86400000);await fails(f.sync.getGrant(f.principal,campaign),'CAMPAIGN_NOT_AUTHORIZED');});

test('V2 command replay binds original payload, no future fabricated source outcomes or partial receipts',async t=>{const f=await setup(t);await f.publish([profileRecord()]);await f.enable(['hp']);const b={commandId:uuid(),expectedGrantRevision:2,operations:[op('adjust_hp','character-profile',profile,{delta:-3})],source:'Explicit fictional damage'};const r=await f.sync.submit(connector,campaign,b);assert.deepEqual(await f.sync.submit(connector,campaign,b),{mode:r.mode,campaignId:campaign,command:r.command});await fails(f.sync.submit(connector,campaign,{...b,source:'Changed source'}),'COMMAND_ID_REUSED');const d=decision(r.command);d.records[0].fields.maximumHp=100;await fails(f.sync.decide(f.principal,campaign,d),'LOCAL_FIELDS_MISMATCH');assert.equal((await f.sync.read(connector,campaign)).records[0].revision,1);});

test('V2 hosted Worker MCP authentication, typed discovery and actual device HTTPS wire envelopes',async t=>{const f=await setup(t),env={DB:f.db,OWNER_SITE_USER_ID:ownerId},url='https://fixture.example',headers={'Content-Type':'application/json',Authorization:'Bearer '+f.secret,'X-Astravar-Credential':f.token.credentialId};const req=(path,body,h=headers)=>new Request(url+path,{method:body===undefined?'GET':'POST',headers:h,...(body===undefined?{}:{body:JSON.stringify(body)})});await f.publish([profileRecord()]);const record=await handleWorker(req('/v2/campaigns/'+campaign+'/records/character-profile/'+profile),env);const value=await record.json();assert.equal(value.mode,'ASTRAVAR_CAMPAIGN_V2');assert.deepEqual(Object.keys(value.record).sort(),['fields','kind','recordId','revision']);const rpc=(name,args)=>({jsonrpc:'2.0',id:1,method:'tools/call',params:{name,arguments:args}});let response=await handleWorker(req('/mcp',rpc('get_campaign_record',{campaignId:campaign,kind:'character-profile',recordId:profile}),{'Content-Type':'application/json','oai-authenticated-user-id':ownerId}),env);assert.equal((await response.json()).result.structuredContent.records[0].fields.currentHp,24);assert.equal((await handleWorker(req('/mcp',rpc('get_campaign_state',{campaignId:campaign})),env)).status,401);const revoked=await handleWorker(req('/v2/campaigns/'+campaign+'/devices/revoke',{}),env);assert.equal((await revoked.json()).mode,'ASTRAVAR_CAMPAIGN_V2');const replay=await handleWorker(req('/v2/campaigns/'+campaign+'/devices/revoke',{}),env);assert.equal((await replay.json()).revoked,true);});

test('V2 unchanged heartbeat binds complete current snapshot and replay never renews stale freshness',async t=>{const f=await setup(t);await f.publish([profileRecord(),walletRecord()]);const g=await f.sync.authorize(f.principal,campaign),snapshot=await f.sync.mirrorSnapshot(g),body={commandId:uuid(),records:[],snapshotFingerprint:snapshot.fingerprint};f.setTime(f.now()+1000);const ack=await f.sync.publish(f.principal,campaign,body);f.setTime(f.now()+300001);const replay=await f.sync.publish(f.principal,campaign,body);assert.equal(replay.publishedAt,ack.publishedAt);assert.equal((await f.sync.read(connector,campaign)).records[0].stale,true);await fails(f.sync.publish(f.principal,campaign,{commandId:uuid(),records:[],snapshotFingerprint:await sha256('missing-records')}),'MIRROR_SNAPSHOT_CONFLICT');await fails(f.sync.publish(f.principal,campaign,{commandId:uuid(),records:[]}),'SNAPSHOT_FINGERPRINT_REQUIRED');});

test('V2 explicit mirror removals use atomic revision CAS and preserve immutable source deletion evidence',async t=>{const f=await setup(t);await f.publish([profileRecord(),walletRecord()]);const cid=uuid(),body={commandId:cid,records:[],removed:[{kind:'wallet',recordId:'fixture-wallet',expectedRevision:1}]};await f.sync.publish(f.principal,campaign,body);assert.equal((await f.sync.read(connector,campaign,{kinds:['wallet']})).records.length,0);assert.deepEqual((await f.sync.publicationReadback(f.principal,campaign,cid)).removed,body.removed);assert.equal((await f.sync.publicationReadback(f.principal,campaign,cid)).records.length,0);assert.deepEqual((await f.sync.publish(f.principal,campaign,body)).removed,body.removed);const bad={commandId:uuid(),records:[{...profileRecord(),revision:2,fields:{...profileRecord().fields,revision:2,currentHp:23}}],removed:[{kind:'wallet',recordId:'missing-wallet',expectedRevision:1}]};await fails(f.sync.publish(f.principal,campaign,bad),'REVISION_CONFLICT');assert.equal((await f.sync.read(connector,campaign,{kinds:['character-profile']})).records[0].fields.currentHp,24);});

test('V2 publication batch readback retrieves current mirror records, not cached publication payload',async t=>{const f=await setup(t),cid=uuid();await f.sync.publish(f.principal,campaign,{commandId:cid,records:[profileRecord(),walletRecord()]});const first=await f.sync.publicationReadback(f.principal,campaign,cid);assert.equal(first.records.length,2);assert.deepEqual(Object.keys(first.records[0]).sort(),['fields','kind','recordId','revision']);await f.publish([{...profileRecord(),revision:2,fields:{...profileRecord().fields,revision:2,currentHp:21}}]);const current=await f.sync.publicationReadback(f.principal,campaign,cid);assert.equal(current.records.find(x=>x.kind==='character-profile').fields.currentHp,21);assert.equal(current.records.find(x=>x.kind==='character-profile').revision,2);});

test('V2 checkpoint selection and active session aggregate prefer newest saved checkpoint, preserve ambiguity',async t=>{const f=await setup(t);const old=envelope('checkpoint','aaa-old',{id:'aaa-old',title:'Old stopping point',scene:'Old',campaignId:campaign}),latest=envelope('checkpoint','zzz-latest',{id:'zzz-latest',title:'Latest saved',scene:'Verified current',campaignId:campaign});old.fields.updatedAt=10;latest.fields.updatedAt=20;await f.publish([profileRecord(),walletRecord(),old,latest]);const checkpoint=await f.sync.latestCheckpoint(connector,campaign);assert.equal(checkpoint.records[0].recordId,'zzz-latest');const session=await f.sync.session(connector,campaign);assert.ok(session.records.some(r=>r.kind==='character-profile'));assert.ok(session.records.some(r=>r.kind==='wallet'));assert.ok(session.records.some(r=>r.recordId==='zzz-latest'));assert.equal(session.records.some(r=>r.kind==='audit'),false);await f.publish([{...latest,recordId:'zzz-other',fields:{...latest.fields,id:'zzz-other'}}]);assert.equal((await f.sync.latestCheckpoint(connector,campaign)).unresolved.length,1);});

test('V2 stage completion updates only the selected confirmed stage and preserves later stages',async t=>{const f=await setup(t),project=envelope('project','fixture-project',{id:'fixture-project',title:'Fictional assembly',description:'',status:'In Progress'}),stage=envelope('stage','fixture-stage',{id:'fixture-stage',projectId:'fixture-project',title:'Resolved stage',notes:'Confirmed completed',status:'In Progress',sortOrder:0}),later=envelope('stage','fixture-later',{id:'fixture-later',projectId:'fixture-project',title:'Later stage',notes:'',status:'Planned',sortOrder:1});await f.publish([project,stage,later]);await f.enable(['engineering']);const {command:c}=await f.submit([op('set_record','stage','fixture-stage',{...stage.fields,status:'Completed'})]);await f.sync.decide(f.principal,campaign,decision(c));const records=(await f.sync.read(connector,campaign,{kinds:['project','stage']})).records;assert.equal(records.find(r=>r.recordId==='fixture-stage').fields.status,'Completed');assert.equal(records.find(r=>r.recordId==='fixture-later').fields.status,'Planned');assert.equal(records.find(r=>r.recordId==='fixture-project').fields.status,'In Progress');});

test('V2 chunked UTF-8 archive retains source identity, hashes and complete text with narrow part reads',async t=>{const f=await setup(t),referenceId='notion-original-source',text='Arcane text 🦉 bronze 金 '.repeat(5000),parts=[];for(let i=0;i<text.length;i+=7000)parts.push(text.slice(i,i+7000));const ref=envelope('reference','archive:fixture:meta',{referenceId,externalId:'notion-source-id',title:'Player-known source',category:'History',campaignId:campaign,sourceUrl:'https://notion.so/fixture',sourceRevision:'verified-r1',contentSha256:await sha256(text),packageHash:'fixture-package',bodySha256:await sha256(text),propertiesSha256:await sha256('{}'),bodyBytes:Buffer.byteLength(text),propertiesBytes:2,bodyParts:parts.length,propertiesParts:1});const chunks=[];for(let i=0;i<parts.length;i++)chunks.push(envelope('reference','archive:fixture:body:'+i,{referenceId,externalId:'notion-source-id',sourceUrl:'https://notion.so/fixture',sourceRevision:'verified-r1',part:'body',index:i,total:parts.length,text:parts[i],contentHash:await sha256(parts[i])}));await f.publish([ref,...chunks]);const metadata=(await f.sync.referencePart(connector,campaign,{referenceId})).records[0];assert.equal(metadata.fields.bodyBytes,Buffer.byteLength(text));assert.equal(metadata.fields.bodyParts,parts.length);let restored='';for(let i=0;i<parts.length;i++){const record=(await f.sync.referencePart(connector,campaign,{referenceId,part:'body',index:i})).records[0];assert.equal(record.fields.contentHash,await sha256(record.fields.text));restored+=record.fields.text;}assert.equal(restored,text);assert.equal(await sha256(restored),metadata.fields.bodySha256);assert.ok(Buffer.byteLength(text)>65536);});

test('V2 narrow continuity grant cannot upload archive chunks or cross-category reference bodies',async t=>{const f=await setup(t,{readScopes:['continuity'],writeScopes:['continuity']});for(const record of [envelope('reference','archive:fixture:meta',{referenceId:'source',title:'Metadata',sourceRevision:'r1'}),envelope('reference','plain-reference',{id:'plain-reference',body:'Raw campaign private cross-category text'})])await fails(f.sync.publish(f.principal,campaign,{commandId:uuid(),records:[record]}),'ARCHIVE_READ_SCOPE_DENIED');});

test('V2 companion-only grant reads and changes its resource without granting player spell-slot authority',async t=>{const f=await setup(t,{readScopes:['companions'],writeScopes:['companions']}),resource=envelope('companion-resource','fixture-eek-resource',{id:'fixture-eek-resource',companionId:'fixture-eek',name:'Ghostwing',current:2,maximum:null});await f.publish([resource]);await f.enable(['companions']);const {command:c}=await f.submit([op('adjust_resource','companion-resource',resource.recordId,{delta:-1})]);assert.equal(c.status,'PENDING_DELIVERY');await f.sync.decide(f.principal,campaign,decision(c,{scopes:['companions']}));assert.equal((await f.sync.read(connector,campaign,{kinds:['companion-resource']})).records[0].fields.current,1);await fails(f.sync.read(connector,campaign,{kinds:['party-sheet']}),'READ_SCOPE_DENIED');});

test('V2 typed schema rejects arbitrary record fields and identity swaps before staging',async t=>{const f=await setup(t);await f.publish([profileRecord()]);await fails(f.submit([op('set_record','character-profile',profile,{...profileRecord().fields,sql:'DROP TABLE campaign'})]),'UNKNOWN_RECORD_FIELD');await fails(f.sync.publish(f.principal,campaign,{commandId:uuid(),records:[{...profileRecord(),fields:{...profileRecord().fields,id:'other'}}]}),'RECORD_IDENTITY_MISMATCH');assert.equal((await f.sync.pending(f.principal,campaign)).commands.length,0);});

