test('V2 read/write permission narrowing is independent, immutable, immediate and cannot re-expand',async t=>{const f=await setup(t);await f.publish([profileRecord(),walletRecord()]);await f.enable(['hp','currency']);const {command:c}=await f.submit([op('adjust_hp','character-profile',profile,{delta:-3})]);const receipt=(await f.sync.decide(f.principal,campaign,decision(c))).receipt;const body={commandId:uuid(),expectedRevision:2,autoSyncScopes:['currency'],readScopes:['character','currency'],writeScopes:['currency']};const narrowed=await f.sync.configureGrant(f.principal,campaign,body);assert.equal(narrowed.grant.revision,3);assert.deepEqual(narrowed.grant.readScopes,['character','currency']);assert.deepEqual(await f.sync.configureGrant(f.principal,campaign,body),narrowed);const row=(await f.sync.read(connector,campaign,{kinds:['character-profile']})).records[0];assert.equal(Object.hasOwn(row.fields,'currentHp'),false);assert.equal((await f.sync.getReceipt(connector,campaign,c.commandId)).receipt.records[0].fields.currentHp,undefined);await fails(f.sync.configureGrant(f.principal,campaign,{commandId:uuid(),expectedRevision:3,autoSyncScopes:['hp'],readScopes:['character','currency','hp'],writeScopes:['currency','hp']}),'GRANT_EXPANSION_REQUIRES_OWNER');const projected={recordId:row.recordId,kind:row.kind,revision:row.revision,fields:row.fields};await f.sync.publish(f.principal,campaign,{commandId:uuid(),records:[projected]});assert.equal((await f.sync.read(connector,campaign,{kinds:['character-profile']})).records[0].revision,receipt.records[0].revision);const none=await f.sync.configureGrant(f.principal,campaign,{commandId:uuid(),expectedRevision:3,autoSyncScopes:[],readScopes:[],writeScopes:[]});assert.equal(none.grant.readScopes.length,0);assert.equal((await f.sync.session(connector,campaign)).records.length,0);const redacted=(await f.sync.getReceipt(connector,campaign,c.commandId)).receipt;assert.equal(redacted.records.length,0);assert.equal(redacted.recordsRedacted,1);assert.equal((await f.sync.getGrant(f.principal,campaign)).grant.revision,4);});

