test('V2 oversized audit metadata and ordered text parts remain recoverable without dominating history list',async t=>{const f=await setup(t),original='fictional-audit-original',text=canonical({id:original,beforeJson:'Private scoped history 🦉'.repeat(4000),afterJson:'Resolved fictional state'.repeat(4000)}),hash=await sha256(text),prefix='audit-part:fixture-hash:',parts=[];for(let i=0;i<text.length;i+=8000)parts.push(text.slice(i,i+8000));const metadata={recordId:original,kind:'audit',revision:1,fields:{id:original,chunked:true,originalRecordId:original,originalKind:'audit',contentSha256:hash,contentBytes:Buffer.byteLength(text),parts:parts.length,encoding:'canonical-json',partIdPrefix:prefix,source:'Original immutable fictional audit'}};const rows=[metadata];for(let i=0;i<parts.length;i++)rows.push({recordId:prefix+i,kind:'audit',revision:1,fields:{originalRecordId:original,originalKind:'audit',contentSha256:hash,index:i,total:parts.length,text:parts[i],partSha256:await sha256(parts[i]),source:'Original immutable fictional audit'}});await f.publish(rows);const list=await f.sync.read(connector,campaign,{kinds:['audit'],metadataOnly:true});assert.equal(list.records.length,1);assert.equal(list.records[0].recordId,original);let restored='';for(let i=0;i<parts.length;i++){const r=(await f.sync.read(connector,campaign,{kinds:['audit'],recordId:metadata.fields.partIdPrefix+i})).records[0];assert.equal(r.fields.partSha256,await sha256(r.fields.text));restored+=r.fields.text;}assert.equal(restored,text);assert.equal(await sha256(restored),metadata.fields.contentSha256);assert.ok(Buffer.byteLength(text)>65536);});

