test('V2 pending queue returns bounded UTF-8 prefixes and drains all large commands without dropping them',async t=>{const f=await setup(t),projects=[];for(let i=0;i<8;i++)projects.push(envelope('project','large-project-'+i,{id:'large-project-'+i,title:'Large project '+i,description:'Old description '.repeat(350),status:'Proposed'}));await f.publish(projects);await f.enable(['engineering']);const ids=[];for(let i=0;i<8;i++){const {command:c}=await f.submit([op('set_record','project','large-project-'+i,{description:'New verified description '.repeat(250)})]);ids.push(c.commandId);}const seen=new Set();let batches=0;for(;;){const pending=await f.sync.pending(f.principal,campaign);assert.ok(Buffer.byteLength(JSON.stringify(pending))<=48*1024);if(!pending.commands.length)break;batches++;if(batches===1){assert.ok(pending.commands.length<8);assert.equal(pending.hasMore,true);}for(const c of pending.commands){assert.equal(seen.has(c.commandId),false);await f.sync.decide(f.principal,campaign,decision(c));seen.add(c.commandId);}}assert.ok(batches>1);assert.equal(seen.size,8);assert.deepEqual([...seen].sort(),ids.sort());});

